using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;
using UnityEngine;using UnityEngine.AI;
using DeliveryService.Mok.Navigation;
namespace DeliveryService.Mok.Editor {
public static class StoryCompanionCheck {
 static string log;static void Check(bool ok,string message){if(!ok)throw new Exception(message);log+="PASS "+message+"\n";File.WriteAllText("Logs/Companion-check.txt",log);}
 static IEnumerator Wait(float duration){float until=Time.time+duration;while(Time.time<until)yield return null;}
 static void ClearPending(StoryPhoneInbox inbox)=>((Queue<StoryPhoneInbox.Message>)typeof(StoryPhoneInbox).GetField("pending",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(inbox)).Clear();
 static void Place(PlayerCombat p,Vector3 point){var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=point+Vector3.up;cc.enabled=true;Physics.SyncTransforms();}
 static void BikePlace(MotorcycleController bike,Vector3 point){var delta=point-bike.transform.position;bike.sphereRB.position+=delta;bike.transform.position+=delta;Physics.SyncTransforms();}
 public static IEnumerator Verify(){
  log="Companion and contact integration\n";var inbox=StoryPhoneInbox.Current;inbox.AutoOpenEnabled=false;yield return Wait(.5f);var m=BrokerMission.Current;var p=m.player;var phone=UnityEngine.Object.FindFirstObjectByType<PhoneController>();phone.ClosePhone();ClearPending(inbox);
  Check(!inbox.mingi.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Mingi cap brim"||t.name=="Mingi orange work cap"),"Mingi hat removed in saved main scene");Check(m.subtitle.GetComponent<StorySpeakerColors>()&&StorySpeakerColors.Format("나: 확인\n실장: 따라와").Contains("#9DDAFF")&&StorySpeakerColors.Format("나: 확인\n실장: 따라와").Contains("#BFE5B5"),"player and other speaker colours differ");
  var mingiPos=inbox.mingi.position;bool active=inbox.mingi.gameObject.activeSelf;inbox.mingi.gameObject.SetActive(true);inbox.mingi.position=m.meeting.position;Place(p,m.meeting.position+inbox.mingi.forward*3);var mingiAnimator=inbox.mingi.GetComponentInChildren<Animator>();mingiAnimator.Play("Idle",0,0);mingiAnimator.Update(.1f);int unread=inbox.Unread;inbox.Send("가까운 대화 검사","바로 옆이니까 직접 얘기할게.",true);yield return null;yield return null;Check(inbox.Messages[0].localConversation&&inbox.Messages[0].read&&inbox.Unread==unread&&inbox.nearbyPanel.activeSelf,"nearby Mingi speaks directly and logs read conversation");
  var cam=p.View;var pos=cam.transform.position;var rot=cam.transform.rotation;cam.transform.position=inbox.mingi.position+inbox.mingi.forward*2.6f+Vector3.up*1.3f;cam.transform.LookAt(inbox.mingi.position+Vector3.up*1.2f);BrokerMissionCheck.Capture(m,"Companion-Mingi");cam.transform.SetPositionAndRotation(pos,rot);inbox.mingi.position=mingiPos;inbox.mingi.gameObject.SetActive(false);inbox.nearbyPanel.SetActive(false);typeof(StoryPhoneInbox).GetField("nearbyUntil",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(inbox,0f);
  inbox.AutoOpenEnabled=true;yield return Wait(.3f);Check(phone.IsPhoneOpen()&&UnityEngine.Object.FindFirstObjectByType<NavigationPlanner>().CurrentScreen==NavigationPlanner.Screen.Missions,"nearby mission briefing opens mission app after conversation");phone.ClosePhone();ClearPending(inbox);
  inbox.Send("먼 곳의 연락 검사","미션 위치를 확인해.",true);var message=inbox.Messages[0];yield return Wait(.25f);var planner=UnityEngine.Object.FindFirstObjectByType<NavigationPlanner>();var app=UnityEngine.Object.FindFirstObjectByType<StoryPhoneApp>();Check(phone.IsPhoneOpen()&&planner.CurrentScreen==NavigationPlanner.Screen.Messages&&app.Detail&&!message.read,"new remote contact opens phone detail without prematurely marking read");yield return Wait(1.2f);Check(message.read,"visible message becomes read");
  inbox.Send("두 번째 연락 검사","첫 메시지를 보고 있을 때 도착한 연락.");var second=inbox.Messages[0];yield return Wait(.3f);Check(!second.read&&app.body.text.Contains("미션 위치를 확인해"),"new arrival does not replace currently viewed message");phone.ClosePhone();yield return Wait(.4f);Check(phone.IsPhoneOpen()&&app.body.text.Contains("첫 메시지를 보고"),"queued message opens after phone is closed");yield return Wait(1.1f);app.Back();app.Refresh();Check(app.rows.Any(r=>r.text.Contains("읽음")),"message list explicitly labels read state");phone.ClosePhone();ClearPending(inbox);
  var bike=UnityEngine.Object.FindFirstObjectByType<MotorcycleController>();bike.EnterBike(p.gameObject);inbox.Send("주행 중 연락 검사","내리면 확인해.");yield return Wait(.3f);Check(!phone.IsPhoneOpen()&&planner.CurrentScreen==NavigationPlanner.Screen.Map,"riding retains navigation and queues contact");bike.ExitBike();yield return Wait(.5f);Check(phone.IsPhoneOpen()&&planner.CurrentScreen==NavigationPlanner.Screen.Messages,"queued contact automatically opens after dismount");phone.ClosePhone();inbox.AutoOpenEnabled=false;ClearPending(inbox);
  m.day.EnterNightPreparation();Check(m.Begin(),"mission starts with passenger setup");Place(p,m.broker.position+m.broker.forward*2);p.View.transform.LookAt(m.broker.position+Vector3.up*1.2f);yield return Wait(.3f);Check(m.Talk(),"broker conversation begins on foot");m.AdvanceDialogue(true);yield return Wait(.2f);Check(!m.passenger.IsRiding&&m.broker.GetComponent<NavMeshAgent>().enabled,"walking arrival retains walking companion");
  foreach(var enemy in UnityEngine.Object.FindObjectsByType<CitizenCombat>(FindObjectsSortMode.None))if(enemy.missionEnemy)UnityEngine.Object.Destroy(enemy.gameObject);m.reinforcementDelay=999;
  BikePlace(bike,m.broker.position+Vector3.back*1.5f+Vector3.up*.2f);yield return Wait(.2f);Check(bike.EnterBike(p.gameObject),"player mounts beside broker");yield return Wait(1.3f);Check(m.passenger.IsRiding&&!m.passenger.IsBoarding&&!m.broker.GetComponent<NavMeshAgent>().enabled,"broker boards rear seat and stops walking navigation");
  int seatIndex=Array.IndexOf(m.passenger.bikes,bike);var hips=m.broker.GetComponentInChildren<Animator>().GetBoneTransform(HumanBodyBones.Hips);Check(Vector3.Distance(hips.position,m.passenger.seats[seatIndex].position)<.15f,"passenger pelvis follows authored rear seat");
  var bikeCam=p.View;pos=bikeCam.transform.position;rot=bikeCam.transform.rotation;bikeCam.transform.position=bike.transform.position+bike.transform.right*3-bike.transform.forward*2+Vector3.up*1.8f;bikeCam.transform.LookAt(bike.transform.position+Vector3.up*.8f);BrokerMissionCheck.Capture(m,"Companion-passenger");bikeCam.transform.SetPositionAndRotation(pos,rot);
  BikePlace(bike,m.exit.position+Vector3.up*.2f);yield return Wait(.4f);Check(Vector3.Distance(m.broker.position,m.exit.position)<3,"passenger follows motorcycle movement");bike.ExitBike();yield return Wait(.4f);Check(!m.passenger.IsRiding&&m.broker.GetComponent<NavMeshAgent>().isOnNavMesh,"broker dismounts onto walkable ground");Place(p,m.exit.position);yield return Wait(4);Check(m.State==BrokerMission.Phase.Debrief,"mounted escape reaches debrief");m.AdvanceDialogue(true);Check(m.Completed,"mounted route completes mission");
  Place(p,m.exit.position+Vector3.forward*4);p.View.transform.rotation=Quaternion.Euler(0,90,0);p.avatar.PoseKick(PlayerAvatar.HitTime);yield return null;yield return null;BrokerMissionCheck.Capture(m,"Companion-punch");Check(p.avatar.leftFist.GetComponentsInChildren<MeshFilter>().All(f=>f.sharedMesh.name.Contains("Faceted")),"saved faceted fist geometry replaces rounded spheres");p.avatar.StopKick();inbox.mingi.gameObject.SetActive(active);
 }
}
}
#endif
